function interpolate({samples, queries}) {
  const map = new Map();
  for (const [t, v] of samples) {
    map.set(t, v);
  }
  const times = Array.from(map.keys()).sort((a, b) => a - b);
  const values = times.map(t => map.get(t));
  return queries.map(q => {
    if (times.length === 0) return null;
    if (q < times[0] || q > times[times.length - 1]) return null;
    const idx = times.indexOf(q);
    if (idx !== -1) return values[idx];
    let lo = 0;
    let hi = times.length - 1;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (times[mid] <= q) lo = mid;
      else hi = mid;
    }
    const t0 = times[lo];
    const t1 = times[hi];
    const v0 = values[lo];
    const v1 = values[hi];
    const num = v0 * (t1 - q) + v1 * (q - t0);
    return Math.floor(num / (t1 - t0));
  });
}

