function available({capacity,events}) {
  const seen = new Set();
  let reserved = 0;
  for (const [id, delta] of events) {
    if (seen.has(id)) continue;
    seen.add(id);
    reserved += delta;
    if (reserved < 0) reserved = 0;
    if (reserved > capacity) reserved = capacity;
  }
  return capacity - reserved;
}

function resolve({start,links,maxHops}) {
  let cur = start;
  const seen = new Set();
  let hops = 0;
  while (Object.hasOwn(links, cur)) {
    if (seen.has(cur)) return null;
    if (hops >= maxHops) return null;
    seen.add(cur);
    cur = links[cur];
    hops++;
  }
  return cur;
}

