function rates({samples,queries,maxAge}) {
  const byTime = new Map();
  for (const [t, v] of samples) {
    byTime.set(t, v);
  }
  const times = Array.from(byTime.keys()).sort((a, b) => a - b);
  return queries.map(q => {
    let lo = 0, hi = times.length - 1, idx = -1;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (times[mid] <= q) {
        idx = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    if (idx === -1) return null;
    const t = times[idx];
    const v = byTime.get(t);
    if (v === null || v === undefined) return null;
    if (q - t > maxAge) return null;
    return v;
  });
}

