function incidents({samples,high,low}) {
  let open = false;
  let streak = 0;
  const out = [];
  for (let i = 0; i < samples.length; i++) {
    const n = samples[i];
    if (open) {
      if (n <= low) {
        open = false;
        streak = 0;
      }
    } else {
      streak = n >= high ? streak + 1 : 0;
      if (streak === 2) {
        open = true;
        out.push(i);
      }
    }
  }
  return out;
}

function layers(jobs) {
  if (jobs === null || typeof jobs !== "object" || Array.isArray(jobs)) {
    return null;
  }
  const names = Object.keys(jobs);
  if (names.length === 0) {
    return [];
  }
  const deps = new Map();
  for (const name of names) {
    const list = jobs[name];
    if (!Array.isArray(list)) {
      return null;
    }
    const set = new Set();
    for (const dep of list) {
      if (typeof dep !== "string" || !Object.prototype.hasOwnProperty.call(jobs, dep)) {
        return null;
      }
      set.add(dep);
    }
    deps.set(name, set);
  }
  const remaining = new Set(names);
  const result = [];
  while (remaining.size > 0) {
    const layer = [];
    for (const name of remaining) {
      let ready = true;
      for (const dep of deps.get(name)) {
        if (remaining.has(dep)) {
          ready = false;
          break;
        }
      }
      if (ready) {
        layer.push(name);
      }
    }
    if (layer.length === 0) {
      return null;
    }
    layer.sort();
    result.push(layer);
    for (const name of layer) {
      remaining.delete(name);
    }
  }
  return result;
}

