function allocate({units, caps, start}) {
  const n = caps.length;
  if (n === 0) return [];
  const result = new Array(n).fill(0);
  let remaining = units;
  let i = start;
  let fullCount = 0;
  for (let k = 0; k < n; k++) {
    if (caps[k] === 0) fullCount++;
  }
  while (remaining > 0 && fullCount < n) {
    if (result[i] < caps[i]) {
      result[i]++;
      remaining--;
      if (result[i] === caps[i]) fullCount++;
    }
    i = (i + 1) % n;
  }
  return result;
}

