      let ready = true;
      for (const dep of deps.get(name)) {
        if (!done.has(dep)) {
          ready = false;
          break;
        }
      }
      if (ready) {
        layer.push(name);
      }
    }
    if (layer.length === 0) {
      return null;
    }
    layer.sort();
    for (const name of layer) {
      done.add(name);
      remaining.delete(name);
    }
    result.push(layer);
  }
  return result;
