  const result = caps.map(() => 0);
  let remaining = units;
  let index = start;
  let active = caps.reduce((acc, cap) => acc + (cap > 0 ? 1 : 0), 0);
  while (remaining > 0 && active > 0) {
    if (caps[index] > 0 && result[index] < caps[index]) {
      result[index]++;
      remaining--;
      if (result[index] === caps[index]) active--;
    }
    index = (index + 1) % caps.length;
  }
  return result;
}

function allocate({units, caps, start}) {
  const n = caps.length;
  if (n === 0) return [];
  const result = new Array(n).fill(0);
  let remaining = units;
  let i = start;
  let active = 0;
  for (let k = 0; k < n; k++) {
    if (caps[k] > 0) active++;
  }
  while (remaining > 0 && active > 0) {
    if (result[i] < caps[i]) {
      result[i]++;
      remaining--;
      if (result[i] === caps[i]) active--;
    }
    i = (i + 1) % n;
  }
  if (remaining === 0) return result;
  // fallback: allocate as evenly as possible respecting caps
  const res = new Array(n).fill(0);
  let totalCap = 0;
  for (let c of caps) totalCap += c;
  let toAllocate = Math.min(units, totalCap);
  while (toAllocate > 0) {
    let allocatedThisRound = false;
    for (let idx = 0; idx < n && toAllocate > 0; idx++) {
      if (res[idx] < caps[idx]) {
        res[idx]++;
        toAllocate--;
        allocatedThisRound = true;
      }
    }
    if (!allocatedThisRound) break;
  }
  return res;
}

function available({capacity,events}) {
  const seen = new Set();
