  for (const [id, delta] of events) {
    if (seen.has(id)) continue;
    seen.add(id);
    reserved += delta;
    if (reserved < 0) reserved = 0;
    if (reserved > capacity) reserved = capacity;
  }
  return capacity - reserved;
}

