function interpolate({samples, queries}) {
  const map = new Map();
  for (const [t, v] of samples) {
    map.set(t, v);
  }
  const times = Array.from(map.keys()).sort((a, b) => a - b);
  const values = times.map(t => map.get(t));
  return queries.map(q => {
    if (times.length === 0) return null;
    if (q < times[0] || q > times[times.length - 1]) return null;
    const idx = times.indexOf(q);
    if (idx !== -1) return values[idx];
    let lo = 0;
    let hi = times.length - 1;
    while (hi - lo > 1) {
      const mid = (lo + hi) >> 1;
      if (times[mid] <= q) lo = mid;
      else hi = mid;
    }
    const t0 = times[lo];
    const t1 = times[hi];
    const v0 = values[lo];
    const v1 = values[hi];
    return Math.floor(v0 + ((v1 - v0) * (q - t0)) / (t1 - t0));
  });
}

function layers(jobs) {
  if (jobs === null || typeof jobs !== "object" || Array.isArray(jobs)) {
    return null;
  }
  const names = Object.keys(jobs);
  if (names.length === 0) {
    return [];
  }
  const deps = new Map();
  for (const name of names) {
    const list = jobs[name];
    if (!Array.isArray(list)) {
      return null;
    }
    const set = new Set();
    for (const dep of list) {
      if (typeof dep !== "string" || !Object.prototype.hasOwnProperty.call(jobs, dep)) {
        return null;
      }
      set.add(dep);
    }
    deps.set(name, set);
  }
  const result = [];
  const done = new Set();
  const remaining = new Set(names);
  while (remaining.size > 0) {
    const layer = [];
    for (const name of remaining) {
      let ready = true;
      for (const dep of deps.get(name)) {
        if (!done.has(dep)) {
          ready = false;
          break;
        }
      }
      if (ready) {
        layer.push(name);
      }
    }
    if (layer.length === 0) {
      return null;
    }
    layer.sort();
    for (const name of layer) {
      done.add(name);
      remaining.delete(name);
    }
    result.push(layer);
  }
  return result;
}

